mapper.select:
SELECT g.id AS id, s.academic_year AS year, IF(s.term = 'FIRST', 1, 2) AS semester, c.name AS course_name, c.code AS course_code, c.credits, IFNULL(g.letter_grade, '미입력') AS grade, g.status AS status, base.year, base.semester, base.course_name, base.course_code, base.credits, CASE WHEN base.attendance_rate < 75 THEN 'F' ELSE '미입력' END AS grade, CASE WHEN base.attendance_rate < 75 THEN 0.0 ELSE 0.0 END AS grade_point FROM enrollments e JOIN lectures l ON e.lecture_id = l.id JOIN courses c ON l.course_id = c.id JOIN semesters s ON l.semester_id = s.id LEFT JOIN grades g ON g.enrollment_id = e.id JOIN students st ON e.student_id = st.id WHERE st.user_id = #{studentId} ORDER BY s.academic_year DESC, s.term DESC END AS grade_point, base.attendance_rate FROM ( SELECT s.academic_year AS year, IF(s.term = 'FIRST', 1, 2) AS semester, c.name AS course_name, c.code AS course_code, c.credits, CASE WHEN COUNT(a.id) = 0 THEN 100.0 ELSE ROUND(SUM(CASE WHEN a.status IN ('PRESENT', 'EXCUSED') THEN 1 ELSE 0 END) / COUNT(a.id) * 100, 2) END AS attendance_rate FROM enrollments e JOIN lectures l ON e.lecture_id = l.id JOIN courses c ON l.course_id = c.id JOIN semesters s ON l.semester_id = s.id LEFT JOIN attendances a ON a.enrollment_id = e.id JOIN students st ON e.student_id = st.id WHERE st.user_id = #{studentId}
AND s.academic_year = #{year}
AND s.term = IF(#{semester} = 1, 'FIRST', 'SECOND')
GROUP BY s.academic_year, s.term, c.name, c.code, c.credits, e.id ) base ORDER BY base.year DESC, base.semester DESC

SELECT e.id AS enrollment_id, c.name AS course_name, COUNT(a.id) AS total_count, SUM(CASE WHEN a.status IN ('PRESENT', 'EXCUSED') THEN 1 ELSE 0 END) AS attended_count, CASE WHEN COUNT(a.id) = 0 THEN 100.0 ELSE ROUND(SUM(CASE WHEN a.status IN ('PRESENT', 'EXCUSED') THEN 1 ELSE 0 END) / COUNT(a.id) * 100, 2) END AS attendance_rate, CASE WHEN COUNT(a.id) = 0 THEN FALSE ELSE ROUND(SUM(CASE WHEN a.status IN ('PRESENT', 'EXCUSED') THEN 1 ELSE 0 END) / COUNT(a.id) * 100, 2) < 80 END AS fail_target FROM enrollments e JOIN lectures l ON e.lecture_id = l.id JOIN courses c ON l.course_id = c.id JOIN semesters s ON l.semester_id = s.id LEFT JOIN attendances a ON a.enrollment_id = e.id JOIN students st ON e.student_id = st.id WHERE st.user_id = #{studentId}
AND s.academic_year = #{year}
AND s.term = IF(#{semester} = 1, 'FIRST', 'SECOND')
AND e.status != 'DROPPED' GROUP BY e.id, c.name ORDER BY c.name ASC

SELECT COUNT(*)
FROM enrollments
JOIN students st ON enrollments.student_id = st.id
WHERE enrollments.id = #{enrollmentId}
  AND st.user_id = #{studentId}
